text:
system {
    name-server 192.0.2.53;
    name-server 198.51.100.53;
    time-zone Asia/Kolkata;
}

system {
    syslog {
        file messages {
            any notice;
            authorization info;
        }
    }
}

system {
    tacplus-options {
        strict-authorization;
        enhanced-accounting;
    }
}

system {
    host-name edge-sw-01;
    domain-name branch.example;
}

system {
    ntp {
        server 192.0.2.10;
        server 192.0.2.11 prefer;
    }
}

interfaces {
    ge-0/0/10 {
        description "Branch transit";
        unit 0 {
            family inet {
                address 192.0.2.65/26;
            }
        }
    }
}

system {
    accounting {
        events interactive-commands;
    }
}

system {
    accounting {
        events login;
    }
}

system {
    ntp {
        server 192.0.2.10 key 5;
        threshold 300 reject;
    }
}

system {
    syslog {
        host 192.0.2.10 {
            any info;
            authorization info;
        }
    }
}

system {
    login {
        retry-options {
            tries-before-disconnect 3;
            backoff-threshold 2;
            backoff-factor 5;
            lockout-period 15;
        }
    }
}

system {
    ntp {
        authentication-key 5 md5 <SECRET>;
        trusted-key 5;
    }
}

system {
    services {
        ssh {
            protocol-version v2;
            root-login deny;
            connection-limit 10;
        }
    }
}

system {
    services {
        ssh {
            rate-limit 20;
            max-sessions-per-connection 3;
        }
    }
}

system {
    authentication-order [ radius tacplus password ];
}

system {
    tacplus-options {
        authorization-time-interval 60;
        timestamp-and-timezone;
    }
}
